//! See https://github.com/google/boringssl/commit/ed00cfde0 and the
//! `PathLenSelfIssuedNotCountedButStillVerified` test in `crypto/x509/x509_test.cc`.
//!
//! Fixtures are generated by `boring/test/generate-path-len-rollover-certs.sh`.

use crate::stack::Stack;
use crate::x509::store::X509StoreBuilder;
use crate::x509::verify::X509VerifyParamRef;
use crate::x509::{X509Ref, X509StoreContext, X509VerifyError, X509VerifyResult, X509};

#[test]
fn test_self_issued_rollover() {
    let root = X509::from_pem(include_bytes!("../../../test/path-len-rollover-root.pem")).unwrap();
    let int2 = X509::from_pem(include_bytes!("../../../test/path-len-rollover-int2.pem")).unwrap();
    let int2_pathlen0 = X509::from_pem(include_bytes!(
        "../../../test/path-len-rollover-int2-pathlen0.pem"
    ))
    .unwrap();
    let rollover = X509::from_pem(include_bytes!(
        "../../../test/path-len-rollover-rollover.pem"
    ))
    .unwrap();
    let rollover_pathlen0 = X509::from_pem(include_bytes!(
        "../../../test/path-len-rollover-rollover-pathlen0.pem"
    ))
    .unwrap();
    let int1 = X509::from_pem(include_bytes!("../../../test/path-len-rollover-int1.pem")).unwrap();
    let leaf = X509::from_pem(include_bytes!("../../../test/path-len-rollover-leaf.pem")).unwrap();

    // Leaf -- Int1 -- Rollover -- Int2 -- Root
    //
    // Rollover is self-issued: it has Int2's name and is signed by Int2's old key, but carries
    // Int2's new key. It does not count towards the path length, so pathlen 1 on both Int2 and
    // Rollover is enough to cover Int1.
    assert_eq!(
        Ok(()),
        verify(&leaf, &[&root], &[&int1, &rollover, &int2], |_| {})
    );

    // Rollover's own pathlen is still enforced, and pathlen 0 does not allow Int1 below it.
    // BoringSSL ignored this before ed00cfde0.
    assert_eq!(
        Err(X509VerifyError::PATH_LENGTH_EXCEEDED),
        verify(&leaf, &[&root], &[&int1, &rollover_pathlen0, &int2], |_| {})
    );

    // Int1 still counts against Int2's pathlen, even with Rollover in between.
    assert_eq!(
        Err(X509VerifyError::PATH_LENGTH_EXCEEDED),
        verify(&leaf, &[&root], &[&int1, &rollover, &int2_pathlen0], |_| {})
    );
}

fn verify(
    cert: &X509Ref,
    trusted: &[&X509Ref],
    untrusted: &[&X509Ref],
    configure: impl FnOnce(&mut X509VerifyParamRef),
) -> X509VerifyResult {
    let trusted = {
        let mut builder = X509StoreBuilder::new().unwrap();

        for cert in trusted {
            builder.add_cert(cert).unwrap();
        }

        builder.build()
    };

    let untrusted = {
        let mut stack = Stack::new().unwrap();

        for cert in untrusted {
            stack.push((**cert).to_owned()).unwrap();
        }

        stack
    };

    let mut store_ctx = X509StoreContext::new().unwrap();

    store_ctx
        .init(&trusted, cert, &untrusted, |ctx| {
            configure(ctx.verify_param_mut());
            ctx.verify_cert().unwrap();

            Ok(ctx.verify_result())
        })
        .expect("failed to obtain X509VerifyResult")
}
